dtsPropsFor.BarChartView:
/** The chart data and configuration. Each datum is one bar. */
  payload: {
    title: string;
    data: { label: string; value: number; color?: string }[];
    orientation: "vertical" | "horizontal";
    xlabel?: string;
    ylabel?: string;
  }

dtsPropsFor.LineChartView:
/** The chart data and configuration. One entry in `series` per line. */
  payload: {
    title: string;
    series: { name: string; data: { x: string | number; y: number }[] }[];
    xlabel?: string;
    ylabel?: string;
  }

dtsPropsFor.PieChartView:
/** The chart data and configuration. Set `variant` to "donut" for a hole; slices beyond `maxSegments` collapse into an expandable "Other". */
  payload: {
    title: string;
    data: { label: string; value: number; color?: string }[];
    variant: "pie" | "donut";
    maxSegments?: number;
  }

dtsPropsFor.ScatterChartView:
/** The chart data and configuration. One entry in `series` per point group; `size` scales the marker. */
  payload: {
    title: string;
    series: { name: string; data: { x: number; y: number; size?: number }[] }[];
    xlabel?: string;
    ylabel?: string;
  }

dtsPropsFor.TreemapView:
/** The chart data. `data` nodes nest via `children` for a hierarchical treemap. */
  payload: {
    title: string;
    data: { label: string; value: number; color?: string; children?: { label: string; value: number; color?: string; children?: unknown[] }[] }[];
  }

dtsPropsFor.HeatmapView:
/** The chart data and configuration. `cells` index into the `xLabels`/`yLabels` axes by position. */
  payload: {
    title: string;
    xLabels: string[];
    yLabels: string[];
    cells: { x: number; y: number; value: number }[];
    xlabel?: string;
    ylabel?: string;
  }

dtsPropsFor.TableView:
/** The table data and configuration. `rows` are keyed by each column's `key`; a `kind: "sparkline"` column's cells are number arrays (oldest → newest). */
  payload: {
    title: string;
    columns: { key: string; label: string; align?: "left" | "right" | "center"; kind?: "text" | "sparkline" }[];
    rows: Record<string, string | number | number[]>[];
    sortable: boolean;
    filterable: boolean;
  }

dtsPropsFor.StatPanelView:
/** The panel data. Each item is a KPI card; `delta` drives a coloured trend arrow, `trend` a sparkline, `target` a progress bar. */
  payload: {
    title: string;
    items: { label: string; value: string | number; unit?: string; delta?: number; deltaUnit?: string; deltaCaption?: string; higherIsBetter?: boolean; description?: string; status?: "success" | "warning" | "danger" | "info"; trend?: number[]; target?: number; badge?: string }[];
    columns?: number;
  }

dtsPropsFor.SankeyView:
/** The flow data. `links` reference nodes by name; `nodes` optionally fixes order and colors. The graph must be acyclic. */
  payload: {
    title: string;
    nodes?: { name: string; color?: string }[];
    links: { source: string; target: string; value: number }[];
    valueLabel?: string;
  }

dtsPropsFor.DashboardView:
/** A grid of tiles; each tile renders another Sigil widget from its own payload. */
  payload: {
    title: string;
    columns?: number;
    tiles: { type: "bar-chart" | "line-chart" | "pie-chart" | "table" | "scatter-chart" | "treemap" | "heatmap" | "stat-panel" | "sankey" | "map"; payload: unknown; colSpan?: number }[];
  }

dtsPropsFor.MapView:
/** The map data. choropleth: `data` shades regions (world: ISO 3166-1 alpha-3 / alpha-2 / numeric / name; us-states: USPS / name / FIPS). bubble: `points` places sized markers at lat/lon. */
  payload: {
    title: string;
    scope: "world" | "us-states";
    variant: "choropleth" | "bubble";
    data?: { id: string; value: number; label?: string }[];
    points?: { lat: number; lon: number; value: number; label?: string }[];
    valueLabel?: string;
  }
